package com.keybindtilehighlight;

import com.google.inject.Provides;
import java.awt.event.KeyEvent;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Keybind Tile Highlight",
		description = "Highlight the tile under the mouse while a keybind is held",
		tags = {"tiles", "overlay", "highlight", "keybind"}
)
public class KeybindTileHighlightPlugin extends Plugin implements KeyListener
{
	@Inject
	private KeybindTileHighlightConfig config;

	@Inject
	private KeybindTileHighlightOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ConfigManager configManager;

	@Getter
	private volatile boolean keybind1Held;

	@Getter
	private volatile boolean keybind2Held;

	@Getter
	private volatile int mostRecentKeybind;

	@Override
	protected void startUp()
	{
		migrateRainbowMode();
		overlayManager.add(overlay);
		keyManager.registerKeyListener(this);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(this);
		overlayManager.remove(overlay);
		keybind1Held = false;
		keybind2Held = false;
		mostRecentKeybind = 0;
	}

	@Provides
	KeybindTileHighlightConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(KeybindTileHighlightConfig.class);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (matches(config.highlightKeybind(), e))
		{
			if (!keybind1Held)
			{
				mostRecentKeybind = 1;
			}
			keybind1Held = true;
		}

		if (matches(config.highlightKeybind2(), e))
		{
			if (!keybind2Held)
			{
				mostRecentKeybind = 2;
			}
			keybind2Held = true;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (matches(config.highlightKeybind(), e))
		{
			keybind1Held = false;
		}

		if (matches(config.highlightKeybind2(), e))
		{
			keybind2Held = false;
		}
	}

	@Override
	public void focusLost()
	{
		keybind1Held = false;
		keybind2Held = false;
	}

	private void migrateRainbowMode()
	{
		String legacyValue = configManager.getConfiguration(KeybindTileHighlightConfig.GROUP, "rainbowMode");
		if (!"true".equals(legacyValue) && !"false".equals(legacyValue))
		{
			return;
		}

		KeybindTileHighlightConfig.RainbowMode migrated = "true".equals(legacyValue)
				? KeybindTileHighlightConfig.RainbowMode.SOLID
				: KeybindTileHighlightConfig.RainbowMode.OFF;
		configManager.setConfiguration(KeybindTileHighlightConfig.GROUP, "rainbowMode", migrated);
	}

	private boolean matches(Keybind keybind, KeyEvent e)
	{
		if (Keybind.NOT_SET.equals(keybind))
		{
			return false;
		}

		int keyCode = e.getExtendedKeyCode();
		Integer eventModifier = Keybind.getModifierForKeyCode(keyCode);

		if (eventModifier != null && keybind.getKeyCode() == KeyEvent.VK_UNDEFINED)
		{
			return (keybind.getModifiers() & eventModifier) == eventModifier;
		}

		return keybind.matches(e);
	}
}

package com.keybindtilehighlight;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class KeybindTileHighlightPluginLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(KeybindTileHighlightPlugin.class);
		RuneLite.main(args);
	}
}
